fn has_cycle(graph: &ArraySeqStEphS<ArraySeqStEphS<usize>>) -> (has_cycle: bool)
    requires
        spec_toposortsteph_wf(graph),
    ensures
        has_cycle == !spec_is_dag(graph),
    ;

fn has_cycle(graph: &ArraySeqStPerS<ArraySeqStPerS<usize>>) -> (has_cycle: bool)
    requires
        spec_cycledetectstper_wf(graph),
    ensures
        has_cycle == !spec_is_dag_per(graph),
    ;
